#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <functional>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> tickets(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> tickets[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& t : tickets) adj[t[0]].push_back((int)t[1]);
    for (auto& lst : adj) sort(lst.begin(), lst.end(), greater<int>());
    vector<int> stack = {1}, trip;
    while (!stack.empty()) {
        int v = stack.back();
        if (!adj[v].empty()) {
            stack.push_back(adj[v].back());
            adj[v].pop_back();
        } else {
            trip.push_back(v);
            stack.pop_back();
        }
    }
    reverse(trip.begin(), trip.end());
    for (size_t i = 0; i < trip.size(); i++) cout << (i ? " " : "") << trip[i];
    cout << "\n";

    return 0;
}

